-- ====================================================================
-- 5. QUOTATION (견적서 105건)
-- 미삭제 104건 / 삭제 1건. 원래 시나리오 5건과 확대 데이터 100건을 함께 등록한다.
-- ====================================================================

-- 견적 00001 | [1] 견적만 : 주문 0 (미주문 현황에 전량 표시)
INSERT INTO QUOTATION (
    QUOTATION_ID, QUOTATION_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID, WAREHOUSE_NAME,
    ASSIGNEE_ID, ASSIGNEE_NAME, NOTE, PROGRESS_STATUS
)
SELECT SEQ_QUOTATION.NEXTVAL, LPAD(TO_CHAR(SEQ_QUOTATION.NEXTVAL), 5, '0'), DATE '2026-09-01',
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00001'), '한빛상사',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00001'), '본사창고',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00001'), '김철수',
       '신규 사무실 장비 견적', 'IN_PROGRESS'
FROM DUAL;

-- 견적 00002 | [2] 부분 주문 : 주문서 2건(00001, 00003)으로 나누어 일부만 주문
INSERT INTO QUOTATION (
    QUOTATION_ID, QUOTATION_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID, WAREHOUSE_NAME,
    ASSIGNEE_ID, ASSIGNEE_NAME, NOTE, PROGRESS_STATUS
)
SELECT SEQ_QUOTATION.NEXTVAL, LPAD(TO_CHAR(SEQ_QUOTATION.NEXTVAL), 5, '0'), DATE '2026-09-02',
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00002'), '미래유통',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00001'), '본사창고',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00002'), '이영희',
       '모니터 교체 견적 - 2회 분할 주문 진행 중', 'IN_PROGRESS'
FROM DUAL;

-- 견적 00003 | [3] 전부 주문 : 미주문 0 (미주문 현황에서 제외)
INSERT INTO QUOTATION (
    QUOTATION_ID, QUOTATION_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID, WAREHOUSE_NAME,
    ASSIGNEE_ID, ASSIGNEE_NAME, NOTE, PROGRESS_STATUS
