-- ====================================================================
-- 7. SALES_ORDER (주문서 106건)
-- 기존 6건과 확대 데이터 100건. 견적 연계와 직접 입력을 포함한다.
-- ====================================================================

-- 주문 00001 | [2] 견적 00002 1차 주문 (판매 전)
INSERT INTO SALES_ORDER (
    SALES_ORDER_ID, SALES_ORDER_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID, WAREHOUSE_NAME,
    ASSIGNEE_ID, ASSIGNEE_NAME, DUE_DATE, NOTE, PROGRESS_STATUS
)
SELECT SEQ_SALES_ORDER.NEXTVAL, LPAD(TO_CHAR(SEQ_SALES_ORDER.NEXTVAL), 5, '0'), DATE '2026-09-03',
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00002'), '미래유통',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00001'), '본사창고',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00002'), '이영희',
       DATE '2026-09-10', '견적 00002 1차 주문', 'IN_PROGRESS'
FROM DUAL;

-- 주문 00002 | [3] 견적 00003 전량 주문 + [6] 전부 판매된 주문 (판매 00001, 00002)
INSERT INTO SALES_ORDER (
    SALES_ORDER_ID, SALES_ORDER_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID, WAREHOUSE_NAME,
    ASSIGNEE_ID, ASSIGNEE_NAME, DUE_DATE, NOTE, PROGRESS_STATUS
)
SELECT SEQ_SALES_ORDER.NEXTVAL, LPAD(TO_CHAR(SEQ_SALES_ORDER.NEXTVAL), 5, '0'), DATE '2026-09-04',
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00003'), '대한전자',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00001'), '본사창고',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00003'), '박민수',
       DATE '2026-09-08', '견적 00003 전량 주문', 'COMPLETED'
FROM DUAL;

-- 주문 00003 | [2] 견적 00002 2차 주문 (판매 전) : 같은 견적 행을 두 번째로 참조
INSERT INTO SALES_ORDER (
    SALES_ORDER_ID, SALES_ORDER_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID, WAREHOUSE_NAME,
    ASSIGNEE_ID, ASSIGNEE_NAME, DUE_DATE, NOTE, PROGRESS_STATUS
)
SELECT SEQ_SALES_ORDER.NEXTVAL, LPAD(TO_CHAR(SEQ_SALES_ORDER.NEXTVAL), 5, '0'), DATE '2026-09-06',
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00002'), '미래유통',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00001'), '본사창고',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00002'), '이영희',
       DATE '2026-09-13', '견적 00002 2차 주문', 'IN_PROGRESS'
FROM DUAL;

-- 주문 00004 | [5] 부분 판매 + [10] 직접 주문 : 노트북은 일부만, 마우스는 전량 판매
INSERT INTO SALES_ORDER (
    SALES_ORDER_ID, SALES_ORDER_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID, WAREHOUSE_NAME,
    ASSIGNEE_ID, ASSIGNEE_NAME, DUE_DATE, NOTE, PROGRESS_STATUS
)
SELECT SEQ_SALES_ORDER.NEXTVAL, LPAD(TO_CHAR(SEQ_SALES_ORDER.NEXTVAL), 5, '0'), DATE '2026-09-07',
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00004'), '서울오피스',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00002'), '제2창고',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00001'), '김철수',
       DATE '2026-09-20', '견적 없이 직접 주문', 'IN_PROGRESS'
FROM DUAL;

-- 주문 00005 | [4] 주문만 + [10] 직접 주문 : 판매 0
