    SALES_ORDER_ID, SALES_ORDER_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID, WAREHOUSE_NAME,
    ASSIGNEE_ID, ASSIGNEE_NAME, DUE_DATE, NOTE, PROGRESS_STATUS
