    SALES_ORDER_LINE_ID, SALES_ORDER_ID, ITEM_ID, ITEM_NAME, SPECIFICATION, UNIT, QUANTITY, UNIT_PRICE,
    SUPPLY_AMOUNT, VAT_AMOUNT, TOTAL_AMOUNT, QUOTATION_LINE_ID,
    NOTE
)
VALUES (SEQ_SALES_ORDER_LINE.NEXTVAL,
        (SELECT SALES_ORDER_ID FROM SALES_ORDER WHERE SALES_ORDER_NO = '00001'),
        (SELECT ITEM_ID FROM ITEM WHERE ITEM_CODE = '00002'), '모니터', '27인치 / QHD', 'EA',
        4, 195000, 780000, 78000, 858000,
        (SELECT QL.QUOTATION_LINE_ID
           FROM QUOTATION_LINE QL
           JOIN QUOTATION Q ON Q.QUOTATION_ID = QL.QUOTATION_ID
           JOIN ITEM I ON I.ITEM_ID = QL.ITEM_ID
          WHERE Q.QUOTATION_NO = '00002' AND I.ITEM_CODE = '00002'),
