       CAST((ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -2) + MOD(19, LAST_DAY(ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -2)) - ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -2) + 1)) AS TIMESTAMP),
       'N'
  FROM DUAL;

