-- ====================================================================
-- 11. SHIP_INSTRUCTION (출하지시서 103건)
-- 기존 3건과 확대 데이터 100건. 판매 연계와 직접 입력을 포함한다.
-- ====================================================================

-- 출하지시 00001 | [8] 판매 00001 연계 : 키보드 전량 + 마우스 일부 지시 (일부 출하되어 진행중)
INSERT INTO SHIP_INSTRUCTION (
    SHIP_INSTRUCTION_ID, SHIP_INSTRUCTION_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID,
    WAREHOUSE_NAME, ASSIGNEE_ID, ASSIGNEE_NAME, NOTE, PLANNED_DATE, PROGRESS_STATUS, DELIVERY_CONTACT,
    DELIVERY_POSTAL_CODE, DELIVERY_ADDRESS
)
SELECT SEQ_SHIP_INST.NEXTVAL, LPAD(TO_CHAR(SEQ_SHIP_INST.NEXTVAL), 5, '0'), DATE '2026-09-06',
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00003'), '대한전자',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00001'), '본사창고',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00003'), '박민수',
       '판매 00001 출하지시 - 마우스는 일부만 지시', DATE '2026-09-08', 'IN_PROGRESS',
       '010-0000-0003', '21984', '인천광역시 연수구 컨벤시아대로 80'
FROM DUAL;

-- 출하지시 00002 | [8] 판매 00003 연계 : 노트북만 지시 (마우스 10은 미지시), 전량 출하되어 완료
INSERT INTO SHIP_INSTRUCTION (
    SHIP_INSTRUCTION_ID, SHIP_INSTRUCTION_NO, BUSINESS_DATE, PARTNER_ID, PARTNER_NAME, WAREHOUSE_ID,
    WAREHOUSE_NAME, ASSIGNEE_ID, ASSIGNEE_NAME, NOTE, PLANNED_DATE, PROGRESS_STATUS, DELIVERY_CONTACT,
    DELIVERY_POSTAL_CODE, DELIVERY_ADDRESS
)
SELECT SEQ_SHIP_INST.NEXTVAL, LPAD(TO_CHAR(SEQ_SHIP_INST.NEXTVAL), 5, '0'), DATE '2026-09-11',
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00004'), '서울오피스',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00002'), '제2창고',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00001'), '김철수',
       '판매 00003 노트북 출하지시', DATE '2026-09-12', 'COMPLETED',
       '010-0000-0004', '04536', '서울특별시 중구 을지로 50, 12층 회의실'
FROM DUAL;

-- 출하지시 00003 | [10] 직접 출하지시 : 판매 없이 작성, 아직 출하 전
