    WAREHOUSE_NAME, ASSIGNEE_ID, ASSIGNEE_NAME, NOTE, PLANNED_DATE, DELIVERY_CONTACT, DELIVERY_POSTAL_CODE,
    DELIVERY_ADDRESS, PROGRESS_STATUS, UPDATED_AT, DELETED_YN
)
SELECT SEQ_SHIP_INST.NEXTVAL,
       LPAD(TO_CHAR(SEQ_SHIP_INST.NEXTVAL), 5, '0'),
       ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + MOD(10, LAST_DAY(ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1)) - ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + 1),
       (SELECT PARTNER_ID FROM BIZ_PARTNER WHERE PARTNER_CODE = '00058'),
       '바른오피스',
       (SELECT WAREHOUSE_ID FROM WAREHOUSE WHERE WAREHOUSE_CODE = '00019'),
       '인천 물류창고',
       (SELECT ASSIGNEE_ID FROM ASSIGNEE WHERE ASSIGNEE_CODE = '00031'),
       '노서윤',
       '추가 출하지시 71',
       (ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + MOD(10, LAST_DAY(ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1)) - ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + 1)) + 1,
       '010-2000-0058',
       '18468',
       '경기도 화성시 동탄대로 635 5층',
       'IN_PROGRESS',
       CAST((ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + MOD(10, LAST_DAY(ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1)) - ADD_MONTHS(TRUNC(SYSDATE, 'MM'), -1) + 1)) AS TIMESTAMP),
       'N'
  FROM DUAL;

