-- 키보드 4 | 원출하지시 00001 키보드 행 | 지시 6 중 4 출하
INSERT INTO SHIPMENT_LINE (
    SHIPMENT_LINE_ID, SHIPMENT_ID, ITEM_ID, ITEM_NAME, SPECIFICATION, UNIT, QUANTITY, SHIP_INSTRUCTION_LINE_ID,
    NOTE
)
VALUES (SEQ_SHIPMENT_LINE.NEXTVAL,
        (SELECT SHIPMENT_ID FROM SHIPMENT WHERE SHIPMENT_NO = '00001'),
        (SELECT ITEM_ID FROM ITEM WHERE ITEM_CODE = '00003'), '키보드', '기계식 / 텐키리스', 'EA',
        4,
        (SELECT IL.SHIP_INSTRUCTION_LINE_ID
           FROM SHIP_INSTRUCTION_LINE IL
           JOIN SHIP_INSTRUCTION SI ON SI.SHIP_INSTRUCTION_ID = IL.SHIP_INSTRUCTION_ID
           JOIN ITEM I ON I.ITEM_ID = IL.ITEM_ID
          WHERE SI.SHIP_INSTRUCTION_NO = '00001' AND I.ITEM_CODE = '00003'),
        '키보드 부분 출하');

